/** The page in French (verbatim) or in another language (courtesy translation, same blocks in the same order). */
export function legalBlocks(page: "privacy" | "legal", lang: Lang): Block[] {
  const fr: Block[] = page === "privacy" ? legal.privacy : legal.notice;
  if (lang === "fr") return fr;
  const t = page === "privacy" ? PRIVACY[lang] : NOTICE[lang];
  return fr.map((b, i) => ({ ...b, t: t[i] ?? b.t }));
}
export const legalFr = (page: "privacy" | "legal"): Block[] => (page === "privacy" ? legal.privacy : legal.notice);
export const LEGAL_COUNTS = { privacy: legal.privacy.length, notice: legal.notice.length, translated: Object.fromEntries(Object.entries(PRIVACY).map(([k, v]) => [k, [v.length, NOTICE[k as Other].length]])) };
